// Sửa nhãn R8 (spec advertising-taxonomy): ảnh có sản phẩm khác với sản phẩm cũ suy ra, sản phẩm chính đứng đầu.
const PRODUCT_IDS_BY_RECORD_ID = Object.freeze({
  "office-signs-wayfinding-02": ["office-signs/wayfinding-building-directories"],
  "office-signs-wayfinding-13": ["office-signs/wayfinding-building-directories"],
  "led-displays-lightboxes-15": ["led-displays/led-screens", "led-displays/scrolling-led-signs"],
  "mobile-retail-05": ["mobile-retail/mobile-counters", "displays-booths/sampling-booths-reception-counters"],
  "print-decals-21": ["printing-decals/decals-banners-canvas", "office-signs/room-signs"],
  "signage-raised-letters-14": ["signage/aluminium-signs-facades", "signage/light-boxes"],
});

const productIdByLegacyKey = new Map(ADVERTISING_TAG_REGISTRY
  .filter((tag) => tag.group === "variant")
  .map((tag) => [tag.id.slice("product-".length), tag.productId]));

export function attachPhotoMetadata(records) {
  return Object.freeze(records.map((record) => {
    const metadata = PHOTO_METADATA_BY_RECORD_ID[record.id];
    const tagIds = PHOTO_TAG_IDS_BY_RECORD_ID[record.id];
    if (!metadata || !tagIds) throw new Error(`Missing authored photo metadata: ${record.id}`);
    // Ảnh mới chỉ mang productKey cũ vẫn tự có sản phẩm mới qua tag variant.
    const productIds = PRODUCT_IDS_BY_RECORD_ID[record.id] ?? [productIdByLegacyKey.get(record.productKey)];
    return Object.freeze({
      ...record,
      descriptionVi: metadata.descriptionVi,
      descriptionEn: metadata.descriptionEn,
      productIds: Object.freeze([...productIds]),
      tagIds: Object.freeze([...tagIds]),
      media: Object.freeze({ ...record.media, source: metadata.source, sha256: metadata.sha256, provenance: metadata.provenance,
        ...(metadata.suggestionPosition ? { suggestionPosition: metadata.suggestionPosition } : {}),
      }),
    });
  }));
}
